import sys, os, csv, json, gzip, io, re
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8-sig')
    return [l for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def files(d):
    out = []
    for r, _, fs in os.walk(d):
        for f in fs:
            out.append(os.path.join(r, f))
    return sorted(out)


def local_to_utc(naive, tz, dst=None, first=True):
    """dst: True/False/None to pick among ambiguous times."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() == b.utcoffset():
        return a.astimezone(UTC)
    if dst is None:
        return a.astimezone(UTC)  # first occurrence
    for c in (a, b):
        if bool(c.dst()) == dst:
            return c.astimezone(UTC)
    return a.astimezone(UTC)


def std_offset(tz, when):
    d = when.astimezone(tz)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s).astimezone(UTC)


def norm_dir(s):
    s = s.strip().upper()
    if s in ('IN', 'CLOCK_IN', 'K', 'I'):
        return 'IN'
    if s in ('OUT', 'CLOCK_OUT', 'G', 'O'):
        return 'OUT'
    return None


def parse_12(t):
    m = re.match(r'^\s*(\d{1,2}):(\d\d):(\d\d)\s*([AaPp][Mm])?\s*$', t)
    h, mi, s, ap = int(m[1]), int(m[2]), int(m[3]), m[4]
    if ap:
        ap = ap.upper()
        h = h % 12 + (12 if ap == 'PM' else 0)
    return h, mi, s


def read_site(site, tzname, fmt, d):
    tz = ZoneInfo(tzname)
    out = []  # (id, emp, dir, utc datetime)
    for p in files(d):
        lines = read_text(p)
        if fmt == 'abbr-csv':
            hdr = None
            for ln in lines:
                row = next(csv.reader([ln]))
                row = [c.strip() for c in row]
                if 'Badge' in row and 'Punch' in row:
                    hdr = row
                    continue
                if hdr is None:
                    continue
                r = dict(zip(hdr, row))
                mo, da, yr = map(int, r['Date'].split('/'))
                h, mi, s = parse_12(r['Time'])
                z = r.get('Zone', '').upper()
                dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
                u = local_to_utc(datetime(yr, mo, da, h, mi, s), tz, dst)
                out.append((r['Record'], r['Badge'], norm_dir(r['Punch']), u))
        elif fmt == 'epoch-jsonl':
            schema = 1
            for ln in lines:
                o = json.loads(ln)
                if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
                    schema = o['schema']
                    continue
                if o.get('heartbeat'):
                    continue
                if schema == 2:
                    pid, emp, dr = o['punch_id'], o['employee'], o['direction']
                    sec = int(o['epoch_ms']) // 1000
                else:
                    pid, emp, dr = o['id'], o['emp'], o['dir']
                    if 'ts_ms' in o:
                        sec = int(o['ts_ms']) // 1000
                    else:
                        sec = int(o['ts'])
                out.append((str(pid), emp, norm_dir(dr), datetime.fromtimestamp(sec, UTC)))
        elif fmt == 'offset-csv':
            rd = csv.DictReader(io.StringIO('\n'.join(lines)), delimiter=';')
            for r in rd:
                out.append((r['punch_id'], r['employee'], norm_dir(r['event']), parse_iso(r['timestamp'])))
        elif fmt == 'legacy-fixed':
            off = None
            for ln in lines:
                t = ln[0]
                if t == 'H':
                    m = ln[13:18].strip()
                    off = None
                    if m and m[0] in '+-':
                        sg = 1 if m[0] == '+' else -1
                        off = sg * timedelta(hours=int(m[1:3]), minutes=int(m[3:5]))
                elif t == 'D':
                    pid = ln[1:9]
                    badge = ln[9:15].strip()
                    dr = norm_dir(ln[15])
                    dt = datetime.strptime(ln[16:30], '%Y%m%d%H%M%S')
                    if off is None:
                        o = std_offset(tz, dt.replace(tzinfo=UTC) - std_offset(tz, dt.replace(tzinfo=UTC)))
                    else:
                        o = off
                    u = (dt - o).replace(tzinfo=UTC)
                    out.append((pid, 'E' + badge, dr, u))
        elif fmt == 'de-tsv':
            hdr = lines[0].split('\t')
            for ln in lines[1:]:
                r = dict(zip(hdr, ln.split('\t')))
                dd, mm, yy = map(int, r['Datum'].split('.'))
                h, mi = map(int, r['Uhrzeit'].split(':'))
                z = r['Zeitzone'].strip().upper()
                dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
                u = local_to_utc(datetime(yy, mm, dd, h, mi), tz, dst)
                out.append((r['Nr'].strip(), r['Ausweis'].strip(), norm_dir(r['Buchung']), u))
        elif fmt == 'local-csv':
            rd = csv.DictReader(io.StringIO('\n'.join(lines)))
            for r in rd:
                u = local_to_utc(datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S'), tz)
                out.append((r['punch_ref'].strip(), r['employee_id'].strip(), norm_dir(r['direction']), u))
        elif fmt == 'local-jsonl':
            for ln in lines:
                o = json.loads(ln)
                p = o['punch']
                u = local_to_utc(datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S'), tz)
                out.append((str(p['id']).strip(), p['badge'], norm_dir(p['type']), u))
        else:
            raise SystemExit('unknown format ' + fmt)
    return out


def main(inp, outf):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    sites = {}
    with open(os.path.join(inp, 'sites.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (r['timezone'].strip(), r['format'].strip())
    tzs = {s: ZoneInfo(v[0]) for s, v in sites.items()}
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, utc]
    ever = set()
    for site, (tzn, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for pid, emp, dr, u in read_site(site, tzn, fmt, d):
            k = (site, pid)
            ever.add(k)
            if k not in punches:
                punches[k] = [emp, dr, u]

    # corrections
    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for p in files(cd):
            lines = read_text(p)
            for r in csv.DictReader(io.StringIO('\n'.join(lines))):
                r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                corr.append(r)
    corr = [c for c in corr if parse_iso(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (parse_iso(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'], c['punch_id'])
        a = c['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = parse_iso(c['time'])
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'], norm_dir(c['type']), parse_iso(c['time'])]
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, u) in punches.items():
        if emp in emps:
            by_emp.setdefault(emp, []).append((u, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(u, site):
        tz = tzs[site]
        l = u.astimezone(tz)
        secs = l.hour * 3600 + l.minute * 60 + l.second
        r = (secs + 180) // 360 * 360
        return u + timedelta(seconds=r - secs)

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def workday(ru, emp):
        return ru.astimezone(tzs[emps[emp]]).date()

    def inper(d):
        return pstart <= d <= pend

    for emp, lst in by_emp.items():
        lst.sort(key=lambda x: x[:4])
        kept = []
        last = None
        for u, _, site, pid, dr in lst:
            if last is not None and last[4] == dr and (u - last[0]).total_seconds() <= 300:
                if inper(workday(rnd(u, site), emp)):
                    exc['duplicates_dropped'] += 1
                continue
            last = (u, 0, site, pid, dr)
            kept.append((rnd(u, site), site, dr))
        shifts = []
        i = 0
        n = len(kept)
        while i < n:
            ru, site, dr = kept[i]
            if dr == 'IN':
                if i + 1 < n and kept[i + 1][2] == 'OUT' and kept[i + 1][0] - ru <= timedelta(hours=16):
                    shifts.append((ru, kept[i + 1][0], site))
                    i += 2
                    continue
                if inper(workday(ru, emp)):
                    exc['open_shifts'] += 1
            else:
                if inper(workday(ru, emp)):
                    exc['orphan_outs'] += 1
            i += 1
        shifts = [s for s in shifts if inper(workday(s[0], emp))]
        shifts.sort(key=lambda s: s[0])
        daily = {}
        weekly = {}
        R = res[emp]
        for a, b, site in shifts:
            wd = workday(a, emp)
            worked = max(0, int((b - a).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            tz = tzs[site]
            night = 0
            t = a
            while t < b:
                h = t.astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 1
                t += timedelta(minutes=1)
            night = min(night, paid)
            before = daily.get(wd, 0)
            dot = max(0, before + paid - 480) - max(0, before - 480)
            daily[wd] = before + paid
            reg_d = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = weekly.get(wk, 0)
            wot = max(0, wb + reg_d - 2400) - max(0, wb - 2400)
            weekly[wk] = wb + reg_d
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(emp, []):
                if ef <= wd:
                    rate = rt
            if rate is None:
                rate = Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            R['shifts'] += 1
            R['paid_minutes'] += paid
            R['overtime_minutes'] += ot
            R['night_minutes'] += night
            R['gross'] += pay

    def money(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return '%d.%02d' % (c // 100, c % 100)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = 0
    outemps = {}
    for e in sorted(emps):
        R = res[e]
        g = money(R['gross'])
        tg += int(g.replace('.', ''))
        for k in tot:
            tot[k] += R[k]
        outemps[e] = {k: R[k] for k in tot}
        outemps[e]['gross'] = g
    tot['gross'] = '%d.%02d' % (tg // 100, tg % 100)
    with open(outf, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=outemps,
                       exceptions=exc, totals=tot), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
